const allTransactions = $input.all();
const chatId = $('Parse History Filter').first().json.chatId;
const categoryFilter = $('Parse History Filter').first().json.categoryFilter;
const dateFilter = $('Parse History Filter').first().json.dateFilter;

let transactions = allTransactions;

if (categoryFilter) {
  transactions = transactions.filter(t => 
    (t.json.category || 'other').toLowerCase() === categoryFilter.toLowerCase()
  );
}

if (dateFilter === 'week') {
  const weekAgo = new Date();
  weekAgo.setDate(weekAgo.getDate() - 7);
  transactions = transactions.filter(t => 
    new Date(t.json.transaction_date) >= weekAgo
  );
}

transactions = transactions.slice(0, 10);

let title = '📋 *Recent Transactions';
if (categoryFilter) title += ` — ${categoryFilter}`;
if (dateFilter === 'week') title += ' — this week';
title += ':*\n\n';

if (transactions.length === 0) {
  return [{ json: { text: '📋 No transactions found.', chatId } }];
}

let msg = title;
transactions.forEach(t => {
  const emoji = t.json.type === 'income' ? '📈' : '📉';
  const sign = t.json.type === 'income' ? '+' : '-';
  const date = t.json.transaction_date.split('T')[0];
  const cat = t.json.category || 'other';
  msg += `${emoji} ${sign}${t.json.amount} KZT | ${cat} | ${date}\n`;
});
msg += '\n💰 Balance: /balance';

return [{ json: { text: msg, chatId } }];

const rows = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (rows.length === 0) {
  return [{ json: { text: '📊 Нет данных за этот месяц.', chatId } }];
}

const emojis = {
  food: '🍕', transport: '🚗', housing: '🏠',
  health: '💊', education: '📚', entertainment: '🎮',
  shopping: '🛍️', utilities: '⚡', salary: '💼',
  freelance: '💻', other: '💳'
};

let totalAll = 0;
rows.forEach(r => { totalAll += parseFloat(r.json.total); });

let statsText = '';
let statsForAI = [];

rows.forEach(r => {
  const cat = r.json.category || 'other';
  const emoji = emojis[cat] || '💳';
  const amount = parseFloat(r.json.total).toFixed(0);
  const pct = r.json.pct;
  const bars = Math.round(pct / 10);
  const bar = '█'.repeat(bars) + '░'.repeat(10 - bars);
  statsText += `${emoji} ${cat}\n${bar} ${pct}%\n💰 ${amount} KZT\n\n`;
  statsForAI.push({ category: cat, amount: parseFloat(amount), percent: pct });
});

return [{
  json: {
    chatId,
    statsText,
    totalAll: totalAll.toFixed(0),
    statsForAI: JSON.stringify(statsForAI)
  }
}];

