const aiResponse = $input.first().json.choices[0].message.content;
const statsText = $('Code in JavaScript2').first().json.statsText;
const totalAll = $('Code in JavaScript2').first().json.totalAll;
const chatId = $('Code in JavaScript2').first().json.chatId;

const msg = `📊 *Статистика расходов — этот месяц:*

${statsText}
📤 Итого расходов: ${totalAll} KZT
💼 Баланс: /balance

🤖 *AI Инсайты:*
${aiResponse}`;

return [{ json: { text: msg, chatId } }];

const text = $('Telegram Trigger').first().json.message.text;
const chatId = $('Telegram Trigger').first().json.message.chat.id;

// Убираем /budget и разбиваем остаток
const withoutCommand = text.replace('/budget', '').trim();
const parts = withoutCommand.split(' ');

if (parts.length < 2) {
  return [{ json: { 
    chatId, 
    error: true, 
    amount: 0, 
    category: '', 
    text: '⚠️ Format: /budget [category] [amount]\n\nExample: /budget food 20000' 
  }}];
}

const category = parts[0].toLowerCase();
const amount = parseFloat(parts[1]);

if (isNaN(amount) || amount <= 0) {
  return [{ json: { 
    chatId, 
    error: true, 
    amount: 0, 
    category: '',
    text: '⚠️ Amount must be a number. Example: /budget food 20000'
  }}];
}

return [{ json: { chatId, category, amount, error: false } }];

const items = $input.all();
const chatId = $('Switch').item.json.message.chat.id;

if (!items || items.length === 0) {
  return [{ json: { chatId, text: "📭 You have no budgets set.\n\nUse: /budget <category> <amount>\nExample: /budget food 20000" } }];
}

let text = "📊 *Your Budgets:*\n\n";

for (const item of items) {
  const row = item.json;
  const category = row.category || "all categories";
  const emoji = row.emoji || "💰";
  const limit = Number(row.limit_amount).toLocaleString();
  const pct = 0;
  const bar = "░".repeat(10);

  text += `${emoji} *${category}*\n`;
  text += `${bar} ${pct}%\n`;
  text += `Limit: ${limit} KZT/month\n\n`;
}

text += "_Use /budget <category> <amount> to update_";

return [{ json: { chatId, text } }];

const row = $input.first().json;
const chatId = $('Switch').item.json.message.chat.id;

if (!row || !row.amount) {
  return [{ json: { chatId, text: "❌ No transactions to delete." } }];
}

const note = row.note || 'transaction';
const type = row.type === 'income' ? '📈' : '📉';

return [{
  json: {
    chatId,
    text: `🗑 Deleted: ${type} *${note}* — ${Number(row.amount).toLocaleString()} KZT\n_${row.transaction_date}_`
  }
}];

const text = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;
const parts = text.trim().split(/\s+/);

let categoryFilter = null;
let dateFilter = null;

if (parts.length > 1) {
  const arg = parts.slice(1).join(' ').toLowerCase();
  if (arg === 'this week') {
    dateFilter = 'week';
  } else {
    categoryFilter = arg;
  }
}

return [{ json: { chatId, categoryFilter, dateFilter } }];
